(* === SAFETY LATCH — place at TOP of program === *)
Fault_State := (Fault_State AND NOT Reset_PB)
                OR (NOT Emergency_Stop)
                OR Abort_PB;

(* Main logic in middle of program ... *)

(* === SAFETY FORCE-OFF — place at BOTTOM of program === *)
(* Executes last so it cannot be overridden by earlier assignments *)
IF Fault_State THEN
    Fill_Valve   := FALSE;
    Mixer_Motor  := FALSE;
    Drain_Valve  := FALSE;
    Batch_Complete := FALSE;
END_IF;
